<script>(function(){'use strict';var endpoint=<?= json_encode(base_url('catalog/loans/lookup'),JSON_UNESCAPED_SLASHES); ?>,form=document.getElementById('manual-loan-form'),submit=document.getElementById('manual-loan-submit');if(!form)return;function esc(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML}function ready(){submit.disabled=!document.getElementById('loan-member-value').value||!document.getElementById('loan-item-value').value}function setup(kind){var search=document.getElementById('loan-'+kind+'-search'),value=document.getElementById('loan-'+kind+'-value'),results=document.getElementById('loan-'+kind+'-results'),preview=document.getElementById('loan-'+kind+'-preview'),timer,controller;search.addEventListener('input',function(){value.value='';preview.classList.remove('show');ready();clearTimeout(timer);var q=search.value.trim();if(q.length<2){results.hidden=true;return}timer=setTimeout(function(){if(controller)controller.abort();controller=new AbortController();results.hidden=false;results.innerHTML='<div class="p-2 small text-secondary">Mencari...</div>';fetch(endpoint+'?type='+kind+'&q='+encodeURIComponent(q),{headers:{'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin',signal:controller.signal}).then(function(r){if(!r.ok)throw Error('Pencarian gagal');return r.json()}).then(function(j){draw(j.data||[])}).catch(function(e){if(e.name!=='AbortError')results.innerHTML='<div class="p-2 small text-danger">'+esc(e.message)+'</div>'})},250)});function draw(rows){if(!rows.length){results.innerHTML='<div class="p-2 small text-secondary">Data tidak ditemukan.</div>';return}results.innerHTML=rows.map(function(r,i){if(kind==='member'){var ident=r.member_no||r.identity_number||r.phone||'';return '<button type="button" class="loan-result" data-i="'+i+'" '+(r.can_borrow?'':'disabled')+'><strong>'+esc(r.full_name)+'</strong><div class="small text-secondary">'+esc(ident)+(r.phone?' · '+esc(r.phone):'')+' · '+r.active_loans+'/'+r.max_active_loans+' pinjaman</div></button>'}var code=r.barcode||r.inventory_number||r.item_code||'';return '<button type="button" class="loan-result" data-i="'+i+'" '+(r.can_borrow?'':'disabled')+'><strong>'+esc(r.title||'Tanpa judul')+'</strong><div class="small text-secondary">'+esc(code)+' · '+esc(r.collection_type||'-')+' · '+esc(r.status||'-')+'</div></button>'}).join('');results.querySelectorAll('.loan-result:not([disabled])').forEach(function(b){b.onclick=function(){select(rows[Number(b.dataset.i)])}})}function select(r){if(kind==='member'){var ident=r.member_no||r.identity_number||r.phone;value.value=ident;search.value=r.full_name+' — '+ident;preview.innerHTML='<div class="title"><i class="ti ti-user-check me-1"></i>'+esc(r.full_name)+'</div><div class="meta">No. anggota: '+esc(r.member_no||'-')+' · NIK: '+esc(r.identity_number||'-')+' · HP: '+esc(r.phone||'-')+' · Pinjaman aktif: '+r.active_loans+'/'+r.max_active_loans+'</div>'}else{var code=r.barcode||r.inventory_number||r.item_code;value.value=code;search.value=(r.title||'Tanpa judul')+' — '+code;preview.innerHTML='<div class="title"><i class="ti ti-book-2 me-1"></i>'+esc(r.title||'Tanpa judul')+'</div><div class="meta">Barcode/induk: '+esc(code)+' · No. panggil: '+esc(r.call_number||'-')+' · Lokasi: '+esc(r.location_name||'-')+' · Status: tersedia</div>'}preview.classList.add('show');results.hidden=true;ready()}document.addEventListener('click',function(e){if(!results.contains(e.target)&&e.target!==search)results.hidden=true})}setup('member');setup('item');form.addEventListener('submit',function(e){if(submit.disabled)e.preventDefault()})})();</script><?php endif; ?>
